    <script>const QUIZZES = {"cybersecurity": ["Cybersecurity Basics", "Test your fundamental knowledge of core cybersecurity concepts.", [["What does the CIA triad stand for?", ["Confidentiality, Integrity, Availability", "Control, Inspection, Authentication", "Confidentiality, Inspection, Authorization", "Cyber, Internet, Access"], 0], ["Which is the strongest password practice?", ["Reuse one long password", "Use unique passwords with a password manager", "Use your birth date", "Use only lowercase letters"], 1], ["What does MFA add to authentication?", ["A second independent factor", "A faster login", "A backup firewall", "A new IP address"], 0], ["What is phishing?", ["A physical cable attack", "A social-engineering attempt to steal information", "A disk cleanup method", "A routing protocol"], 1], ["What does least privilege mean?", ["Everyone gets admin access", "Users receive only access they need", "All accounts are public", "Passwords never expire"], 1], ["What is a vulnerability?", ["A confirmed software feature", "A weakness that can be exploited", "A type of backup", "A network cable"], 1], ["What is encryption primarily used for?", ["Protecting data confidentiality", "Increasing CPU speed", "Deleting logs", "Assigning IP addresses"], 0], ["What does a firewall commonly control?", ["Network traffic based on rules", "Monitor brightness", "Keyboard input", "File compression"], 0], ["Why are security patches important?", ["They can fix known vulnerabilities", "They always add games", "They remove backups", "They disable authentication"], 0], ["What is an incident response plan for?", ["Preparing to detect, contain and recover from incidents", "Designing websites", "Buying hardware", "Creating passwords"], 0]]], "linux": ["Linux Fundamentals", "Questions on basic to intermediate Linux concepts and commands.", [["Which command prints the current directory?", ["pwd", "cd", "ls", "who"], 0], ["Which command lists directory contents?", ["mkdir", "ls", "touch", "cat"], 1], ["What does chmod change?", ["File permissions", "Hostname", "IP address", "Kernel version"], 0], ["Which directory commonly contains system configuration files?", ["/etc", "/home", "/tmp", "/media"], 0], ["Which command changes directories?", ["mv", "cd", "cp", "grep"], 1], ["What does sudo commonly allow?", ["Running commands with elevated privileges", "Deleting the kernel", "Changing hardware", "Opening a browser"], 0], ["Which command searches text using patterns?", ["grep", "sleep", "clear", "date"], 0], ["What does ps display?", ["Processes", "Partitions only", "Passwords", "Packages only"], 0], ["Which permission letter means execute?", ["x", "r", "w", "e"], 0], ["What is SSH mainly used for?", ["Secure remote access", "Disk formatting", "Image editing", "Local printing"], 0]]], "networking": ["Networking Basics", "Test your knowledge of IP, DNS, subnetting, routing and more.", [["What does DNS translate?", ["Domain names to IP addresses", "MAC addresses to passwords", "Ports to files", "Users to groups"], 0], ["Which protocol is connection-oriented?", ["TCP", "UDP", "ICMP", "ARP"], 0], ["What is the purpose of a subnet mask?", ["Identify network and host portions of an IP", "Encrypt traffic", "Resolve DNS", "Assign MAC addresses"], 0], ["Which device primarily forwards packets between networks?", ["Router", "Switch", "Hub", "Repeater"], 0], ["What port is commonly associated with HTTPS?", ["443", "21", "25", "110"], 0], ["What does DHCP provide?", ["Automatic network configuration such as IP addresses", "File encryption", "Web pages", "CPU scheduling"], 0], ["Which address identifies a network interface at Layer 2?", ["MAC address", "URL", "Port number", "Subnet mask"], 0], ["What does ping commonly use?", ["ICMP", "FTP", "SMTP", "SSH"], 0], ["What is NAT used for?", ["Translating network addresses", "Hashing passwords", "Scanning files", "Compressing packets"], 0], ["Which protocol is commonly used to securely transfer files over SSH?", ["SFTP", "HTTP", "TFTP", "POP3"], 0]]], "ethical-hacking": ["Ethical Hacking", "Explore your understanding of authorized security testing and methodologies.", [["What is the first requirement for ethical hacking?", ["Authorization and defined scope", "Publicly posting findings", "Disabling logging", "Using any target"], 0], ["What is reconnaissance?", ["Collecting information about a target", "Deleting evidence", "Encrypting backups", "Writing malware"], 0], ["Which tool is commonly used for network discovery?", ["Nmap", "WordPad", "Calculator", "Paint"], 0], ["What is vulnerability scanning?", ["Finding known weaknesses with automated checks", "Guessing passwords manually", "Editing source code only", "Changing DNS records"], 0], ["What does enumeration try to identify?", ["Detailed services, users or resources", "Monitor color", "CPU temperature only", "Wallpaper files"], 0], ["What is a proof of concept (PoC)?", ["A controlled demonstration that a weakness can be exploited", "A legal contract", "A password list", "A backup archive"], 0], ["Why should testing stay within scope?", ["To avoid unauthorized impact", "To make scans slower", "To hide results", "To bypass all controls"], 0], ["What is post-engagement reporting for?", ["Documenting findings, evidence and remediation", "Deleting all logs", "Selling credentials", "Changing the target"], 0], ["What is privilege escalation?", ["Gaining higher privileges than initially obtained", "Reducing bandwidth", "Changing a browser theme", "Creating a DNS record"], 0], ["What is responsible disclosure?", ["Reporting a vulnerability appropriately to the affected party", "Publishing secrets immediately", "Ignoring the issue", "Selling the exploit"], 0]]], "web-security": ["Web Security", "Test your knowledge of OWASP, XSS, SQL injection and secure web development.", [["What does XSS stand for?", ["Cross-Site Scripting", "Cross-System Security", "XML Secure Service", "External Site Scan"], 0], ["What is SQL injection caused by?", ["Unsafe handling of untrusted input in SQL queries", "Strong passwords", "TLS certificates", "Image compression"], 0], ["What helps prevent SQL injection?", ["Parameterized queries", "String concatenation everywhere", "Disabling HTTPS", "Using GET only"], 0], ["What does CSRF target?", ["A user’s authenticated browser session", "A hard drive", "A DNS server", "A compiler"], 0], ["What does HTTPS provide?", ["Encrypted transport with TLS", "Database backups", "Malware removal", "Code compilation"], 0], ["What is IDOR?", ["Unauthorized access by manipulating object references", "A DNS attack", "A password manager", "A logging format"], 0], ["Why use output encoding?", ["To reduce injection/XSS risk when displaying untrusted data", "To speed up DNS", "To create accounts", "To disable cookies"], 0], ["What is a secure session cookie commonly marked with?", ["HttpOnly and Secure attributes", "Public and Open", "Debug and Test", "Admin and Root"], 0], ["What is a content security policy (CSP)?", ["A browser-enforced policy that restricts allowed content sources", "A database engine", "A VPN protocol", "A password hash"], 0], ["Why validate authorization server-side?", ["Client-side checks can be bypassed", "It makes CSS faster", "It removes cookies", "It changes DNS"], 0]]], "python": ["Python for Security", "Basic Python concepts for cybersecurity and automation.", [["Which symbol starts a Python comment?", ["#", "//", "<!--", "/*"], 0], ["Which type stores an ordered mutable collection?", ["list", "tuple", "set only", "bool"], 0], ["How do you define a function?", ["def", "func", "function", "define"], 0], ["What does len() return?", ["Length/number of items", "File size only", "CPU usage", "IP address"], 0], ["Which library is commonly used for HTTP requests?", ["requests", "numpy", "tkinter", "random"], 0], ["What does a dictionary store?", ["Key-value pairs", "Only numbers", "Only strings", "Network packets"], 0], ["Which statement handles exceptions?", ["try/except", "if/else only", "for/while", "switch/case"], 0], ["What is a virtual environment used for?", ["Isolating project dependencies", "Encrypting disks", "Scanning ports", "Changing DNS"], 0], ["Which method converts JSON text into Python data?", ["json.loads()", "json.open()", "json.parsefile()", "json.decodeall()"], 0], ["Why is input validation important in security scripts?", ["It reduces unexpected and unsafe input handling", "It guarantees anonymity", "It disables logging", "It removes authentication"], 0]]], "forensics": ["Digital Forensics", "Evidence and investigation concepts.", [["What is digital forensics?", ["Collection and analysis of digital evidence", "Network design", "Graphic editing", "Password creation"], 0], ["Why preserve evidence integrity?", ["To ensure it is not altered and remains trustworthy", "To make files smaller", "To speed up the CPU", "To hide metadata"], 0], ["What is a forensic image?", ["A bit-for-bit copy of storage media", "A screenshot", "A compressed photo", "A browser cache"], 0], ["What is a hash commonly used for in forensics?", ["Verifying data integrity", "Opening encrypted files", "Assigning IPs", "Changing permissions"], 0], ["What should investigators document?", ["Chain of custody and evidence handling", "Only the final conclusion", "Passwords of unrelated users", "Personal opinions"], 0], ["What is volatile data?", ["Data that can disappear when power is removed", "Archived paper records", "Printed files", "Read-only media"], 0], ["Which source can contain browser artifacts?", ["Browser history/cache", "Monitor brightness", "Keyboard cable", "Power adapter"], 0], ["What is metadata?", ["Data describing other data", "A firewall rule", "A password", "A network cable"], 0], ["Why use write blockers?", ["To prevent accidental writes to evidence media", "To increase Wi-Fi speed", "To encrypt email", "To delete malware"], 0], ["What is timeline analysis?", ["Ordering events by time to reconstruct activity", "Changing file names", "Formatting disks", "Scanning ports"], 0]]], "tools": ["Security Tools", "Identify common security tools and their legitimate uses.", [["Nmap is primarily used for?", ["Network discovery and port scanning", "Video editing", "Password storage", "Document writing"], 0], ["Wireshark is used to?", ["Capture and analyze network traffic", "Compile code", "Manage certificates", "Create backups"], 0], ["Burp Suite is commonly used for?", ["Web application security testing", "Disk partitioning", "Email hosting", "Graphic design"], 0], ["What does Metasploit provide?", ["A framework for security testing and exploitation research", "A password vault only", "A web browser", "A DNS resolver"], 0], ["What does Wappalyzer help identify?", ["Technologies used by websites", "CPU temperature", "File permissions", "User passwords"], 0], ["What is Nuclei commonly used for?", ["Template-based vulnerability scanning", "Video streaming", "Database backups", "Text editing"], 0], ["What is a SIEM used for?", ["Centralized security event collection and analysis", "Image resizing", "Source control only", "DNS registration"], 0], ["What is tcpdump?", ["A command-line packet capture tool", "A password manager", "A web framework", "A file compressor"], 0], ["Why should security tools be used with authorization?", ["They can affect systems and expose sensitive information", "They only work offline", "They cannot generate traffic", "They are games"], 0], ["What should tool output be treated as?", ["Evidence/data that requires validation and context", "Always perfect truth", "A password", "A legal verdict"], 0]]], "awareness": ["Cyber Awareness", "Everyday digital safety and security decisions.", [["What should you do with an unexpected login alert?", ["Verify through an official channel and secure the account if needed", "Click every link immediately", "Ignore it forever", "Share the code publicly"], 0], ["Why avoid unknown USB devices?", ["They can contain malicious files or firmware attacks", "They improve security automatically", "They increase storage speed", "They are always encrypted"], 0], ["What is a safer approach to public Wi-Fi?", ["Use HTTPS/VPN where appropriate and avoid sensitive actions on untrusted networks", "Disable all security", "Share passwords", "Use any pop-up certificate"], 0], ["What is social engineering?", ["Manipulating people into revealing information or taking actions", "A routing protocol", "Disk encryption", "A backup method"], 0], ["Why enable automatic updates?", ["They often include security fixes", "They remove all data", "They disable MFA", "They create passwords"], 0], ["What should you do with a suspicious attachment?", ["Verify the sender and context before opening", "Forward it to everyone", "Disable antivirus", "Run it as admin"], 0], ["Which is safer for account recovery?", ["Unique recovery methods and updated contact details", "Public recovery codes", "Shared passwords", "Same password everywhere"], 0], ["What is shoulder surfing?", ["Observing someone to steal sensitive information", "Scanning a subnet", "Encrypting a file", "Cleaning a screen"], 0], ["Why lock your workstation?", ["To prevent unauthorized local access", "To speed up the network", "To clear logs", "To update DNS"], 0], ["What should you do if you suspect a breach?", ["Report it promptly and follow the organization’s incident process", "Delete all evidence", "Hide it from security staff", "Post credentials online"], 0]]]};
        (function () {const THEME_KEY = 'cyberhunt_theme', USER_KEY = 'cyberhunt_user', root = document.documentElement; function setTheme(t) {const safe = t === 'dark' ? 'dark' : 'light'; root.dataset.theme = safe; try {localStorage.setItem(THEME_KEY, safe)} catch (e) { } const b = document.getElementById('themeToggle'); if (b) b.textContent = safe === 'dark' ? '☀' : '☾';} let saved = null; try {saved = localStorage.getItem(THEME_KEY)} catch (e) { } setTheme(saved || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')); document.getElementById('themeToggle')?.addEventListener('click', () => setTheme(root.dataset.theme === 'dark' ? 'light' : 'dark')); document.getElementById('menuToggle')?.addEventListener('click', () => document.getElementById('navLinks')?.classList.toggle('open')); document.getElementById('coursesNav')?.addEventListener('click', function (e) {if (matchMedia('(max-width:760px)').matches) {e.preventDefault(); this.closest('.course-dropdown')?.classList.toggle('open')} }); try {const u = JSON.parse(localStorage.getItem(USER_KEY) || 'null'); const a = document.getElementById('accountBtn'); if (u && a) {a.href = 'dashboard.php'; a.innerHTML = 'Dashboard <span>→</span>'} } catch (e) { } })();
        (function () {const key = new URLSearchParams(location.search).get('id') || 'cybersecurity', data = QUIZZES[key] || QUIZZES.cybersecurity; let idx = 0, score = 0, answered = false, results = []; const title = document.getElementById('quizTitle'), desc = document.getElementById('quizDesc'), count = document.getElementById('questionCount'), progress = document.getElementById('quizProgress'), q = document.getElementById('questionText'), grid = document.getElementById('answerGrid'), feedback = document.getElementById('feedback'), next = document.getElementById('nextBtn'), restart = document.getElementById('restartBtn'), stage = document.getElementById('quizStage'), result = document.getElementById('resultStage'); title.textContent = data[0]; desc.textContent = data[1]; function render() {answered = false; next.disabled = true; feedback.textContent = ''; const item = data[2][idx]; count.textContent = `Question ${idx + 1} of ${data[2].length}`; progress.style.width = `${((idx + 1) / data[2].length) * 100}%`; q.textContent = item[0]; grid.innerHTML = ''; item[1].forEach((answer, i) => {const b = document.createElement('button'); b.type = 'button'; b.className = 'answer-btn'; b.textContent = answer; b.addEventListener('click', () => choose(i, b)); grid.appendChild(b)})} function choose(i, btn) {if (answered) return; answered = true; const item = data[2][idx], correct = item[2];[...grid.children].forEach((b, n) => {b.disabled = true; if (n === correct) b.classList.add('correct')}); if (i === correct) {score++; feedback.textContent = 'Correct — keep going.'; feedback.style.color = '#16804a'} else {btn.classList.add('wrong'); feedback.textContent = 'Not quite. The correct answer is highlighted.'; feedback.style.color = 'var(--red)'} results.push({q: item[0], ok: i === correct, answer: item[1][correct]}); next.disabled = false; next.textContent = idx === data[2].length - 1 ? 'Finish Quiz →' : 'Next →'} function finish() {stage.hidden = true; result.hidden = false; const pct = Math.round(score / data[2].length * 100); window.dispatchEvent(new CustomEvent('cyberhunt:quiz-finished',{detail:{quizId:key,quizTitle:data[0],score,totalQuestions:data[2].length}})); result.innerHTML = `<div class="score-ring" style="--score:${pct * 3.6}deg"><strong>${score}/${data[2].length}</strong></div><h2>Quiz Complete</h2><p style="color:var(--muted)">You scored <b>${pct}%</b> on ${data[0]}.</p><div class="dash-actions" style="justify-content:center;margin-top:15px"><button class="btn btn-dark" id="retryQuiz" type="button">Try Again →</button><a class="btn btn-outline" href="quizzes.php">Back to Quizzes</a></div><div class="review-grid">${results.map((r, n) => `<div class="review-item"><b>${n + 1}. ${r.q}</b><small>${r.ok ? '✓ Correct' : '✕ Incorrect'} · Correct answer: ${r.answer}</small></div>`).join('')}</div>`; document.getElementById('retryQuiz').addEventListener('click', reset)} function reset() {idx = 0; score = 0; results = []; stage.hidden = false; result.hidden = true; render()} next.addEventListener('click', () => {if (!answered) return; if (idx === data[2].length - 1) finish(); else {idx++; render()} }); restart.addEventListener('click', reset); render()})();</script>
